cat > main.go <<'EOF'
// Command wsdl2go generates Go client and server stubs from a WSDL document.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"log"
	"os"
	"path/filepath"
)

// appVersion is the version reported by the -v flag.
const appVersion = "v0.5.0"

var (
	showVersion = flag.Bool("v", false, "Shows gowsdl version")
	pkgFlag     = flag.String("p", "myservice", "Package under which code will be generated")
	outFlag     = flag.String("o", "myservice.go", "File where the generated code will be saved")
	dirFlag     = flag.String("d", "./", "Directory under which package directory will be created")
	insecure    = flag.Bool("i", false, "Skips TLS Verification")
	exportTypes = flag.Bool("make-public", true, "Make the generated types public/exported")
)

func init() {
	log.SetFlags(0)
	log.SetOutput(os.Stdout)
	log.SetPrefix("\U0001F340  ")
}

func printUsage() {
	fmt.Fprintf(os.Stderr, "Usage: %s [options] myservice.wsdl\n", os.Args[0])
	flag.PrintDefaults()
}

func main() {
	flag.Usage = printUsage
	flag.Parse()

	if *showVersion {
		log.Println(appVersion)
		os.Exit(0)
	}

	if len(os.Args) < 2 {
		flag.Usage()
		os.Exit(0)
	}

	// The WSDL location is always taken from the very last argument.
	wsdlPath := os.Args[len(os.Args)-1]

	if *outFlag == wsdlPath {
		log.Fatalln("Output file cannot be the same WSDL file")
	}

	gen, err := newGenerator(wsdlPath, *pkgFlag, *insecure, *exportTypes)
	if err != nil {
		log.Fatalln(err)
	}

	code, err := gen.run()
	if err != nil {
		log.Fatalln(err)
	}

	pkgDir := filepath.Join(*dirFlag, *pkgFlag)
	_ = os.Mkdir(pkgDir, 0744)

	mainFile, err := os.Create(filepath.Join(pkgDir, *outFlag))
	if err != nil {
		log.Fatalln(err)
	}
	defer mainFile.Close()

	buf := new(bytes.Buffer)
	buf.Write(code.header)
	buf.Write(code.types)
	buf.Write(code.operations)

	formatted, err := format.Source(buf.Bytes())
	if err != nil {
		mainFile.Write(buf.Bytes())
		log.Fatalln(err)
	}
	mainFile.Write(formatted)

	srvFile, err := os.Create(pkgDir + "/" + "server" + *outFlag)
	if err != nil {
		log.Fatalln(err)
	}
	defer srvFile.Close()

	srvBuf := new(bytes.Buffer)
	srvBuf.Write(code.serverHeader)
	srvBuf.Write(code.serverWSDL)
	srvBuf.Write(code.server)

	srvFormatted, err := format.Source(srvBuf.Bytes())
	if err != nil {
		srvFile.Write(srvBuf.Bytes())
		log.Fatalln(err)
	}
	srvFile.Write(srvFormatted)

	log.Println("Done \U0001F44D")
}
EOF
echo ok"}

