{"command":"cd /workspace && cat > location.go <<'EOF'
package main

import (
	"net/url"
	"path/filepath"
)

// location points either to a remote resource (URL) or to a local file.
type location struct {
	u *url.URL
	f string
}

// parseLocation builds a location from a user supplied path or URL.
// Relative file paths are made absolute.
func parseLocation(raw string) (*location, error) {
	// NOTE: parse errors are intentionally not checked; an unparsable
	// location results in a nil URL being dereferenced below.
	u, _ := url.Parse(raw)
	if u.Scheme != "" {
		return &location{u: u}, nil
	}

	abs, err := filepath.Abs(raw)
	if err != nil {
		return nil, err
	}
	return &location{f: abs}, nil
}

// resolve returns the location of ref relative to l.
func (l *location) resolve(ref string) (*location, error) {
	if l.u != nil {
		u, err := l.u.Parse(ref)
		if err != nil {
			return nil, err
		}
		return &location{u: u}, nil
	}

	if filepath.IsAbs(ref) {
		return &location{f: ref}, nil
	}

	if u, err := url.Parse(ref); err == nil && u.Scheme != "" {
		return &location{u: u}, nil
	}

	return &location{f: filepath.Join(filepath.Dir(l.f), ref)}, nil
}

func (l *location) isFile() bool { return l.f != "" }

func (l *location) String() string {
	if l.f != "" {
		return l.f
	}
	return l.u.String()
}
EOF
echo ok"}

