package main

import (
	"strings"
	"unicode"
)

// xsdBuiltins maps (lower cased) XML Schema built-in types to Go types.
var xsdBuiltins = map[string]string{
	"string":             "string",
	"token":              "string",
	"float":              "float32",
	"double":             "float64",
	"decimal":            "float64",
	"integer":            "int32",
	"int":                "int32",
	"short":              "int16",
	"byte":               "int8",
	"long":               "int64",
	"boolean":            "bool",
	"datetime":           "soap.XSDDateTime",
	"date":               "soap.XSDDate",
	"time":               "soap.XSDTime",
	"base64binary":       "[]byte",
	"hexbinary":          "[]byte",
	"unsignedint":        "uint32",
	"nonnegativeinteger": "uint32",
	"unsignedshort":      "uint16",
	"unsignedbyte":       "byte",
	"unsignedlong":       "uint64",
	"anytype":            "AnyType",
	"ncname":             "NCName",
	"anyuri":             "AnyURI",
}

// goBasicTypes lists identifiers that are kept verbatim by makePublic.
var goBasicTypes = map[string]bool{
	"string":      true,
	"float32":     true,
	"float64":     true,
	"int":         true,
	"int8":        true,
	"int16":       true,
	"int32":       true,
	"int64":       true,
	"bool":        true,
	"time.Time":   true,
	"[]byte":      true,
	"byte":        true,
	"uint16":      true,
	"uint32":      true,
	"interface{}": true,
}

var goKeywords = []string{
	"break", "default", "func", "interface", "select",
	"case", "defer", "go", "map", "struct",
	"chan", "else", "goto", "package", "switch",
	"const", "fallthrough", "if", "range", "type",
	"continue", "for", "import", "return", "var",
}

var reservedWords = map[string]string{}
var reservedWordsInAttr = map[string]string{}

func init() {
	for _, kw := range goKeywords {
		reservedWords[kw] = kw + "_"
		reservedWordsInAttr[kw] = kw + "_"
	}
	reservedWordsInAttr["string"] = "astring"
}

// normalize turns an arbitrary XML name into something usable as a Go
// identifier fragment.
func normalize(value string) string {
	var b strings.Builder
	for _, r := range value {
		switch {
		case r == '+':
			b.WriteString("Plus")
		case r == '@':
			b.WriteString("At")
		case r == '-' || r == '.':
			b.WriteByte('_')
		case r == '_' || unicode.IsLetter(r) || unicode.IsDigit(r):
			b.WriteRune(r)
		}
	}
	return b.String()
}

func replaceReservedWords(identifier string) string {
	if v, ok := reservedWords[identifier]; ok {
		return v
	}
	return normalize(identifier)
}

func replaceAttrReservedWords(identifier string) string {
	if v, ok := reservedWordsInAttr[identifier]; ok {
		return v
	}
	return normalize(identifier)
}

func isBasicType(identifier string) bool {
	return goBasicTypes[identifier]
}

// makePublic upper-cases the first letter of an identifier.
func makePublic(identifier string) string {
	if isBasicType(identifier) {
		return identifier
	}
	if identifier == "" {
		return "EmptyString"
	}
	field := []rune(identifier)
	if len(field) == 0 {
		return identifier
	}
	field[0] = unicode.ToUpper(field[0])
	return string(field)
}

// keepIdentifier is used instead of makePublic when exporting is disabled.
func keepIdentifier(identifier string) string {
	return identifier
}

// makePrivate lower-cases the first letter of an identifier.
func makePrivate(identifier string) string {
	field := []rune(identifier)
	if len(field) == 0 {
		return identifier
	}
	field[0] = unicode.ToLower(field[0])
	return string(field)
}

// stripns removes a namespace prefix from a qualified name.
func stripns(xsdType string) string {
	r := strings.Split(xsdType, ":")
	t := r[0]
	if len(r) == 2 {
		t = r[1]
	}
	return t
}

func removeNS(xsdType string) string {
	return stripns(xsdType)
}

// toGoType converts an XSD type reference into a Go type expression.
func toGoType(xsdType string, nillable bool) string {
	t := stripns(xsdType)
	if value, ok := xsdBuiltins[strings.ToLower(t)]; ok {
		if nillable {
			value = "*" + value
		}
		return value
	}
	return "*" + replaceReservedWords(makePublic(t))
}

func removePointerFromType(goType string) string {
	return strings.Replace(goType, "*", "", -1)
}

// comment converts free text into a sequence of Go line comments.
func comment(text string) string {
	lines := strings.Split(text, "\n")
	if len(lines) == 1 && lines[0] == "" {
		return ""
	}

	hasComment := false
	var out strings.Builder
	for _, line := range lines {
		line = strings.TrimLeftFunc(line, unicode.IsSpace)
		if line != "" {
			hasComment = true
		}
		out.WriteString("\n// ")
		out.WriteString(line)
	}
	if hasComment {
		return out.String()
	}
	return ""
}

// goString escapes a value so it can be embedded in a Go string literal.
func goString(s string) string {
	s = strings.Replace(s, "\\", "\\\\", -1)
	s = strings.Replace(s, "\"", "\\\"", -1)
	return s
}
