	g.rawWSDL = data

	rootNS := collectXmlns(g.wsdl.Attrs)
	for _, schema := range g.wsdl.Types.Schemas {
		schema.xmlns = map[string]string{}
		for k, v := range rootNS {
			schema.xmlns[k] = v
		}
		for k, v := range collectXmlns(schema.Attrs) {
			schema.xmlns[k] = v
		}
	}

	for _, schema := range g.wsdl.Types.Schemas {
		if err := g.resolveExternals(schema, g.loc); err != nil {
			return err
		}
