func collectXmlns(attrs []xml.Attr) map[string]string {
	m := map[string]string{}
	for _, a := range attrs {
		if a.Name.Space == "xmlns" {
			m[a.Name.Local] = a.Value
		}
	}
	return m
}

func (g *generator) resolveExternals(schema *xsdSchema, loc *location) error {
	download := func(base *location, ref string) error {
		target, err := base.resolve(ref)
		if err != nil {
			return err
		}
		key := target.String()
		if g.resolved[key] {
			return nil
		}
		if g.resolved == nil {
			g.resolved = make(map[string]bool)
		}
		g.resolved[key] = true

		data, err := g.fetch(target)
		if err != nil {
			return err
		}

		newSchema := new(xsdSchema)
		if err := xml.Unmarshal(data, newSchema); err != nil {
			return err
		}
		newSchema.xmlns = collectXmlns(newSchema.Attrs)

		if (len(newSchema.Includes) > 0 || len(newSchema.Imports) > 0) &&
			maxRecursion > g.recursionLevel {
			g.recursionLevel++
			if err := g.resolveExternals(newSchema, target); err != nil {
				return err
			}
		}

		g.wsdl.Types.Schemas = append(g.wsdl.Types.Schemas, newSchema)
		return nil
	}

	for _, imp := range schema.Imports {
		if imp.SchemaLocation == "" {
			log.Printf("[WARN] Don't know where to find XSD for %s", imp.Namespace)
			continue
		}
		if err := download(loc, imp.SchemaLocation); err != nil {
			return err
		}
	}

	for _, inc := range schema.Includes {
		if err := download(loc, inc.SchemaLocation); err != nil {
			return err
		}
	}

	return nil
}

