func (g *generator) getNS() string {
	return g.currentNS
}

// findType returns the type (or element name) carried by a WSDL message.
func (g *generator) findType(message string) string {
	message = stripns(message)

	for _, msg := range g.wsdl.Messages {
		if msg.Name != message {
			continue
		}

		if len(msg.Parts) == 0 {
			log.Printf("[WARN] %s message doesn't have any parts, ignoring message...", msg.Name)
			continue
		}

		part := msg.Parts[0]
		if part.Type != "" {
			return stripns(part.Type)
		}

		elRef := stripns(part.Element)
		for _, schema := range g.wsdl.Types.Schemas {
			for _, el := range schema.Elements {
				if strings.EqualFold(elRef, el.Name) {
					if el.Type != "" {
						return stripns(el.Type)
					}
					return el.Name
				}
			}
		}
	}
	return ""
}

// findSOAPAction looks up the soapAction of an operation in the bindings
// associated with the given port type.
func (g *generator) findSOAPAction(operation, portType string) string {
	for _, binding := range g.wsdl.Bindings {
		if !strings.EqualFold(stripns(binding.Type), portType) {
			continue
		}
		for _, op := range binding.Operations {
			if op.Name == operation {
				return op.SOAPOperation.SOAPAction
			}
		}
	}
	return ""
}

// findNameByType returns the name of the element using the given type when
// it is unambiguous, otherwise the type name itself.
func (g *generator) findNameByType(name string) string {
	found := ""
	ambiguous := false
	var visitElems func(elems []*xsdElement)
	var visitComplex func(ct *xsdComplexType)
	visitElem := func(el *xsdElement) {
		if el.Type != "" && stripns(el.Type) == name {
			if found == "" {
				found = el.Name
			} else if found != el.Name {
				ambiguous = true
			}
		}
		if el.ComplexType != nil {
			visitComplex(el.ComplexType)
		}
	}
	visitElems = func(elems []*xsdElement) {
		for _, el := range elems {
			visitElem(el)
		}
	}
	visitComplex = func(ct *xsdComplexType) {
		visitElems(ct.Sequence)
		visitElems(ct.Choice)
		visitElems(ct.SequenceChoice)
		visitElems(ct.All)
		visitElems(ct.ComplexContent.Extension.Sequence)
		visitElems(ct.ComplexContent.Extension.Choice)
		visitElems(ct.ComplexContent.Extension.SequenceChoice)
	}

	for _, schema := range g.wsdl.Types.Schemas {
		visitElems(schema.Elements)
		for _, ct := range schema.ComplexTypes {
			visitComplex(ct)
		}
	}

	if found == "" || ambiguous {
		return name
	}
	return found
}

