package main

import (
	"encoding/xml"
	"strings"
)

// resolver walks a schema and resolves attribute references, copying the
// referenced attribute definitions in place.
type resolver struct {
	current *xsdSchema
	all     []*xsdSchema
}

func newResolver(current *xsdSchema, all []*xsdSchema) *resolver {
	return &resolver{current: current, all: all}
}

func (r *resolver) run() {
	for _, ct := range r.current.ComplexTypes {
		r.complexType(ct)
	}
	for _, el := range r.current.Elements {
		r.element(el)
	}
}

func (r *resolver) elements(elems []*xsdElement) {
	for _, el := range elems {
		r.element(el)
	}
}

func (r *resolver) element(el *xsdElement) {
	if el.ComplexType != nil {
		r.complexType(el.ComplexType)
	}
}

func (r *resolver) complexType(ct *xsdComplexType) {
	r.elements(ct.Sequence)
	r.elements(ct.Choice)
	r.elements(ct.SequenceChoice)
	r.elements(ct.All)
	r.attributes(ct.Attributes)
	r.attributes(ct.ComplexContent.Extension.Attributes)
	r.elements(ct.ComplexContent.Extension.Sequence)
	r.elements(ct.ComplexContent.Extension.Choice)
	r.elements(ct.ComplexContent.Extension.SequenceChoice)
	r.attributes(ct.SimpleContent.Extension.Attributes)
}

func (r *resolver) attributes(attrs []*xsdAttribute) {
	for _, attr := range attrs {
		if attr.Ref != "" {
			ref := r.globalAttribute(attr.Ref)
			if ref != nil && ref.Ref == "" {
				r.attributes([]*xsdAttribute{ref})
				attr.Name = ref.Name
				attr.Type = ref.Type
				if attr.Fixed == "" {
					attr.Fixed = ref.Fixed
				}
			}
		} else if attr.Type == "" && attr.SimpleType != nil {
			attr.Type = attr.SimpleType.Restriction.Base
		}
	}
}

func (r *resolver) qname(name string) xml.Name {
	parts := strings.SplitN(name, ":", 2)
	if len(parts) == 1 {
		return xml.Name{Local: parts[0], Space: r.current.xmlns[""]}
	}
	return xml.Name{Local: parts[1], Space: r.current.xmlns[parts[0]]}
}

func (r *resolver) globalAttribute(name string) *xsdAttribute {
	ref := r.qname(name)
	for _, schema := range r.all {
		if schema.TargetNamespace != ref.Space {
			continue
		}
		for _, attr := range schema.Attributes {
			if attr.Name == ref.Local {
				return attr
			}
		}
	}
	return nil
}
